import math

def diagonal_gaussian_kl(mu, logvar):
    if len(mu) == 0 or len(mu) != len(logvar):
        raise ValueError("nonempty matching latent dimensions are required")
    if not all(math.isfinite(float(v)) for v in [*mu, *logvar]):
        raise ValueError("parameters must be finite")
    try:
        result = 0.5 * sum(float(m)**2 + math.exp(float(lv)) - 1 - float(lv)
                           for m, lv in zip(mu, logvar))
    except OverflowError as error:
        raise ValueError("variance overflow") from error
    if not math.isfinite(result):
        raise ValueError("nonfinite KL")
    return result

